using System.Collections.Concurrent;
using Apogeu.BuildingBlocks.Contracts;
using Apogeu.Operators.Contracts;
using Apogeu.Security.Tests.Support;

namespace Apogeu.Wallet.Tests.Support;

/// <summary>
/// Double of the operator wallet configuration (SPEC-0046 §6: <c>walletMode demo|seamless</c>, default demo, and the wallet
/// URL of SPEC-0038): every operator is demo unless the test turns it seamless with the URL of the operator test server and
/// an API key generated by the test (never a real credential, ADR-0014). The test can change an operator while operations
/// are pending (SPEC-0046 G4): switch it to demo, forget its configuration or make the lookup fail.
/// </summary>
internal sealed class FixedOperatorWalletSettings : IOperatorWalletSettings
{
    private static readonly OperatorWalletSettings DemoSettings = new(WalletMode.Demo, WalletUrl: null, Key: null);

    private readonly ConcurrentDictionary<OperatorId, OperatorWalletSettings> _settings = new();
    private readonly ConcurrentDictionary<OperatorId, bool> _failing = new();

    /// <summary>Turns <paramref name="op"/> seamless: its wallet is at <paramref name="walletUrl"/> and the calls are signed with <paramref name="key"/>.</summary>
    public FixedOperatorWalletSettings UseSeamless(OperatorId op, Uri walletUrl, TestApiKey key)
    {
        ArgumentNullException.ThrowIfNull(key);
        _settings[op] = new OperatorWalletSettings(WalletMode.Seamless, walletUrl, new OperatorWalletKey(key.Id, key.Secret));
        return this;
    }

    /// <summary>Turns <paramref name="op"/> seamless without a wallet URL nor key (a misconfigured operator: <c>not_configured</c>).</summary>
    public FixedOperatorWalletSettings UseSeamlessWithoutWallet(OperatorId op)
    {
        _settings[op] = new OperatorWalletSettings(WalletMode.Seamless, WalletUrl: null, Key: null);
        return this;
    }

    /// <summary>Turns <paramref name="op"/> back to demo explicitly (the mode switched while operations are pending).</summary>
    public FixedOperatorWalletSettings UseDemo(OperatorId op)
    {
        _settings[op] = DemoSettings;
        return this;
    }

    /// <summary>Forgets the configuration of <paramref name="op"/> (as if it disappeared): it falls back to the default.</summary>
    public FixedOperatorWalletSettings Forget(OperatorId op)
    {
        _settings.TryRemove(op, out _);
        return this;
    }

    /// <summary>While <paramref name="failing"/>, the lookup of <paramref name="op"/> throws (a store failure of the settings).</summary>
    public FixedOperatorWalletSettings FailLookup(OperatorId op, bool failing)
    {
        _failing[op] = failing;
        return this;
    }

    public Task<OperatorWalletSettings> GetAsync(OperatorId op, CancellationToken ct) =>
        _failing.TryGetValue(op, out var failing) && failing
            ? throw new InvalidOperationException($"The wallet settings of operator {op.Value} could not be read (test double).")
            : Task.FromResult(_settings.TryGetValue(op, out var settings) ? settings : DemoSettings);
}
